import crypto from 'crypto';
import http from 'http';

// The webhook secret generated by Stripe CLI
const WEBHOOK_SECRET = 'whsec_31ecf89cd31b8205696761bd007142fe2513595590ff1707d2bbd28bb26b73fa';

// Create a realistic checkout.session.completed event
const event = {
  id: 'evt_test_cli_completed',
  type: 'checkout.session.completed',
  api_version: '2025-05-28.basil',
  created: Math.floor(Date.now() / 1000),
  data: {
    object: {
      id: 'cs_test_cli_' + Date.now(),
      object: 'checkout.session',
      customer: 'cust_test_cli_' + Date.now(),
      customer_details: {
        email: 'test-cli@codexlabs.local'
      },
      customer_email: 'test-cli@codexlabs.local',
      mode: 'payment',
      payment_status: 'paid',
      line_items: [
        {
          id: 'li_test_cli',
          object: 'item',
          price: {
            id: 'price_test_hcdp_individual',
            lookup_key: 'hcdp_individual',
            currency: 'usd',
            unit_amount: 9900
          },
          quantity: 1
        }
      ]
    }
  },
  livemode: false,
  pending_webhooks: 1,
  request: { id: null, idempotency_key: null }
};

// Convert event to JSON string
const eventPayload = JSON.stringify(event);

// Create signature
const timestamp = Math.floor(Date.now() / 1000);
const signedContent = `${timestamp}.${eventPayload}`;
const signature = crypto
  .createHmac('sha256', WEBHOOK_SECRET)
  .update(signedContent)
  .digest('hex');
const stripeSignature = `t=${timestamp},v1=${signature}`;

console.log('Event Payload:', eventPayload);
console.log('Stripe Signature:', stripeSignature);
console.log('\n[CLI Smoke Test] Sending checkout.session.completed event...\n');

// Send to webhook
const options = {
  hostname: 'localhost',
  port: 3000,
  path: '/webhook',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'stripe-signature': stripeSignature,
    'Content-Length': eventPayload.length
  }
};

const req = http.request(options, (res) => {
  let data = '';
  res.on('data', (chunk) => { data += chunk; });
  res.on('end', () => {
    console.log(`\n[CLI Test Response] Status: ${res.statusCode}`);
    console.log(`[CLI Test Response] Body: ${data}`);
    console.log('\n✓ CLI Smoke Test Complete\n');
  });
});

req.on('error', (e) => {
  console.error(`[CLI Test Error] ${e.message}`);
  process.exit(1);
});

req.write(eventPayload);
req.end();
